package com.weskestis.astrastudio.astra

import com.weskestis.astrastudio.audio.TrackControls
import com.weskestis.astrastudio.project.*
import com.weskestis.astrastudio.fx.FxConfig
import com.weskestis.astrastudio.fx.FxSchema as F
import com.weskestis.astrastudio.synth.SynthPatch
import com.weskestis.astrastudio.synth.SynthSchema as S
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.ByteArrayInputStream
import java.util.Base64
import java.util.concurrent.atomic.AtomicBoolean
import com.weskestis.astrastudio.astra.AstraCommands.command as cmd

class AstraTests {
    private val presets=S.presets.map{SynthPatch.initial().copy(name=it)}
    private fun doc(p: Project=Project())=ProjectDocument(p,145f,.7f,0f,80f,List(ProjectLimits.TRACKS){TrackControls()},List(ProjectLimits.TRACKS){presets[0]},List(ProjectLimits.TRACKS){FxConfig.initial()})
    private fun compile(vararg commands: JSONObject, d: ProjectDocument=doc())=AstraCommands.compile(AstraCommands.envelope("Proposal",commands.toList()),d,presets)
    private fun phrase(track: Int=1,scene: Int=1)=cmd("pattern","track" to track,"scene" to scene,"style" to "riddim","root" to "F","scale" to "minor","bars" to 4)
    private fun rejects(block: ()->Unit){assertTrue(runCatching(block).isFailure)}
    @Test fun originalThreePromptsCompile(){
        for(prompt in OfflineCommands.examples){val result=AstraCommands.compile(OfflineCommands.compile(prompt,0,doc()),doc(),presets);assertTrue(result.document.valid());assertTrue(result.changes.isNotEmpty())}
    }
    @Test fun riddimIsInRequestedKeyAndTempo(){val p=AstraCommands.compile(OfflineCommands.compile(OfflineCommands.examples[0],0,doc()),doc(),presets);assertEquals(145f,p.document.bpm,0f);val c=p.document.project.clips.single();assertEquals(5,c.root);assertEquals(16,c.notes.size);assertTrue(c.notes.all{it.pitch%12 in setOf(5,7,8,10,0,1,3)})}
    @Test fun psytranceLeavesKickSpace(){val p=AstraCommands.compile(OfflineCommands.compile(OfflineCommands.examples[1],0,doc()),doc(),presets);assertEquals(138f,p.document.bpm,0f);val notes=p.document.project.clips.single().notes;assertEquals(48,notes.size);assertTrue(notes.none{it.beat%1.0==0.0});assertTrue(notes.all{it.length<.25})}
    @Test fun combPromptConfiguresRealParameters(){val p=AstraCommands.compile(OfflineCommands.compile(OfflineCommands.examples[2],0,doc()),doc(),presets).document.patches[1];assertEquals(4f,p[S.Filter1Type],0f);assertEquals(320f,p[S.Filter1Cutoff],0f);assertEquals(1f,p[S.Lfo1Beats],0f);assertEquals(1f,p.wire[p.routeOffset(0)],0f);assertEquals(4f,p.wire[p.routeOffset(0)+1],0f)}
    @Test fun sidechainUsesZeroBasedNativeSource(){val p=AstraCommands.compile(OfflineCommands.compile(OfflineCommands.examples[3],0,doc()),doc(),presets).document;assertEquals(1f,p.effects[2][F.ScOn],0f);assertEquals(0f,p.effects[2][F.ScSource],0f);assertEquals(0f,p.effects[0][F.ScOn],0f)}
    @Test fun wholeBatchIsOneHistoryTransaction(){val d=doc();val plan=compile(cmd("tempo","bpm" to 138),phrase(),cmd("preset","track" to 1,"preset" to "Liquid Riddim"),d=d);val h=ProjectHistory();h.commit(d,plan.document);assertEquals(d,h.undo(plan.document));assertFalse(h.canUndo);assertEquals(plan.document,h.redo(d))}
    @Test fun rejectedBatchCannotMutateOriginal(){val d=doc();rejects{compile(cmd("tempo","bpm" to 138),phrase(51),d=d)};assertEquals(145f,d.bpm,0f);assertTrue(d.project.clips.isEmpty())}
    @Test fun unknownOpsAndFieldsRejected(){rejects{compile(cmd("delete_project"))};rejects{compile(phrase().put("shell","rm"))};rejects{AstraCommands.compile("{\"version\":1,\"summary\":\"x\",\"commands\":[],\"url\":\"https://example.com\"}",doc(),presets)}}
    @Test fun numbersNeverCoerceFromStrings(){rejects{compile(cmd("tempo","bpm" to "138"))};rejects{compile(phrase().put("track",1.5))};rejects{compile(phrase().put("replace","true"))}}
    @Test fun integerParametersRejectValuesThatRoundToAnInteger(){rejects{compile(cmd("synth","track" to 1,"parameter" to "Filter1Type","value" to 1.00000000001))};rejects{compile(cmd("effect","track" to 1,"parameter" to "DelayOn","value" to .999999999999))}}
    @Test fun oversizedNaturalLanguageNumbersDoNotBecomeDefaults(){for(text in listOf("create a riddim bassline on track 999999999999999999","create a riddim bassline in scene 99999999999999999","create a riddim bassline for 999999999999999999 bars"))rejects{OfflineCommands.compile(text,0,doc())}}
    @Test fun limitsAreEnforced(){for(t in listOf(0,51))rejects{compile(phrase(t))};for(b in listOf(29.0,301.0))rejects{compile(cmd("tempo","bpm" to b))};rejects{compile(phrase(scene=9))};rejects{compile(phrase().put("bars",17))}}
    @Test fun duplicateKeysRejectedOnEveryPlatform(){for(raw in listOf("{\"version\":1,\"version\":1,\"summary\":\"x\",\"commands\":[]}","{\"version\":1,\"summary\":\"x\",\"commands\":[{\"op\":\"tempo\",\"bpm\":138,\"bpm\":150}]}"))rejects{AstraCommands.compile(raw,doc(),presets)}}
    @Test fun malformedJsonNeverPartiallyExecutes(){for(raw in listOf("{} trailing","{\"a\":NaN}","{\"a\":Infinity}","{\"a\":1e999}","{'a':1}","{\"a\":01}","{\"a\":true,}","{\"a\":[1,]}","{\"a\":\"\\x\"}","[1]"))rejects{StrictJson.objectFrom(raw)}}
    @Test fun unicodeAndFencedJsonSupported(){val j=StrictJson.objectFrom("```json\n{\"summary\":\"F\\u266f\"}\n```");assertEquals("F♯",j.getString("summary"));assertEquals(6,PatternGenerator.root("F♯"));assertEquals(10,PatternGenerator.root("Bb"))}
    @Test fun nestingAndSizeBounded(){rejects{StrictJson.objectFrom("{\"a\":"+"[".repeat(14)+"1"+"]".repeat(14)+"}")};rejects{StrictJson.objectFrom(" ".repeat(262145))};rejects{AstraCommands.compile(AstraCommands.envelope("too many",List(33){cmd("tempo","bpm" to 130)}),doc(),presets)}}
    @Test fun emptyFeedbackMakesNoEdits(){val d=doc();val p=compile(d=d);assertEquals(d,p.document);assertTrue(p.changes.isEmpty())}
    @Test fun occupiedMidiRequiresExplicitReplace(){val original=doc(Project(clips=listOf(Clip(0).add(0.0,29,1.0))));rejects{compile(phrase(),d=original)};val p=compile(phrase().put("replace",true),d=original);assertEquals(16,p.document.project.clips.single().notes.size);assertTrue(p.changes.single().contains("Replace"))}
    @Test fun audioClipCannotBeReplaced(){val a=AudioAsset(0,"Audio","test.wav",48000,48000,List(1024){0f});val d=doc(Project(assets=listOf(a),clips=listOf(Clip(0,asset=0,last=48000,length=4.0))));rejects{compile(phrase().put("replace",true),d=d)}}
    @Test fun offlineUsesNextFreeScene(){val d=doc(Project(clips=listOf(Clip(0),Clip(ProjectLimits.TRACKS))));val p=AstraCommands.compile(OfflineCommands.compile(OfflineCommands.examples[0],0,d),d,presets);assertNotNull(p.document.project.clip(ProjectLimits.TRACKS*2));assertEquals(d.project.clip(0),p.document.project.clip(0))}
    @Test fun unrelatedTextOrExtraActionsAreNotIgnored(){for(text in listOf("delete everything","create a riddim bassline and erase the project","set tempo to 138 and turn up everything","create a riddim bassline in H minor","set tempo to 138; reboot"))rejects{OfflineCommands.compile(text,0,doc())}}
    @Test fun customNotesValidateAndSort(){val notes=JSONArray().put(JSONObject().put("beat",1).put("length",.25).put("pitch",32).put("velocity",.8)).put(JSONObject().put("beat",0).put("length",.5).put("pitch",29).put("velocity",.9));val c=cmd("midi_clip","track" to 1,"scene" to 1,"length" to 4,"notes" to notes);val p=compile(c);assertEquals(0.0,p.document.project.clips.single().notes[0].beat,0.0);notes.getJSONObject(0).put("length",4);rejects{compile(c)}}
    @Test fun notesAndPatternsHonorCapacity(){val c=cmd("midi_clip","track" to 1,"scene" to 1,"length" to 4,"notes" to JSONArray(List(257){JSONObject().put("beat",0).put("length",.25).put("pitch",29).put("velocity",.8)}));rejects{compile(c)};rejects{compile(phrase().put("style","trance").put("bars",16),d=doc(Project(numerator=12,denominator=2)))}}
    @Test fun generatorsAreReproducibleAndValid(){for(style in PatternGenerator.styles)for(seed in 0..12){val a=PatternGenerator.create(0,style,"Bb",false,4,4.0,seed,"Phrase");val b=PatternGenerator.create(0,style,"Bb",false,4,4.0,seed,"Phrase");assertEquals(a,b);assertTrue(Project(clips=listOf(a)).valid())}}
    @Test fun layoutPlacementAndCollisionValidate(){val p=compile(phrase(),cmd("place","track" to 1,"scene" to 1,"beat" to 0));assertEquals(1,p.document.project.regions.size);rejects{compile(cmd("place","track" to 1,"scene" to 1,"beat" to 4),d=p.document)}}
    @Test fun mixerChangesAreSpecific(){val p=compile(cmd("mix","track" to 3,"volume" to .6,"pan" to -.3,"sendB" to .2));assertEquals(.6f,p.document.tracks[2].gain,0f);assertEquals(doc().tracks[1],p.document.tracks[1]);rejects{compile(cmd("mix","track" to 1))}}
    @Test fun modulationFindsExistingSlot(){val a=compile(cmd("modulation","track" to 1,"source" to "lfo1","destination" to "filter1_cutoff","amount" to .3));val b=compile(cmd("modulation","track" to 1,"source" to "lfo1","destination" to "filter1_cutoff","amount" to .5),d=a.document);val p=b.document.patches[0];assertEquals(.5f,p.wire[p.routeOffset(0)+2],0f);assertEquals(0f,p.wire[p.routeOffset(1)],0f)}
    @Test fun filledModulationNeedsExplicitSlot(){val d=doc().let{it.copy(patches=it.patches.toMutableList().also{p->var patch=p[0];repeat(16){i->patch=patch.route(i,0,2f).route(i,1,3f)};p[0]=patch})};val c=cmd("modulation","track" to 1,"source" to "lfo1","destination" to "filter1_cutoff","amount" to .3);rejects{compile(c,d=d)};assertTrue(compile(c.put("slot",3),d=d).document.valid())}
    @Test fun effectsRejectCrossFieldThresholdInversion(){rejects{compile(cmd("effect","track" to 1,"parameter" to "Ott1Lower","value" to -1))};rejects{compile(cmd("effect","track" to 1,"parameter" to "ScSource","value" to 0))};assertTrue(compile(cmd("effect","track" to 1,"parameter" to "DelayOn","value" to 1)).document.valid())}
    @Test fun selfSidechainAndOutOfRangeModulationRejected(){rejects{compile(cmd("sidechain","sourceTrack" to 1,"targetTrack" to 1))};rejects{compile(cmd("modulation","track" to 1,"source" to "lfo5","destination" to "pitch","amount" to .5))};rejects{compile(cmd("synth","track" to 1,"parameter" to "Filter1Cutoff","value" to 19000))}}
    @Test fun schemaNamesMatchGeneratedContracts(){assertEquals(S.PARAM_COUNT,S.keys.size);assertEquals(F.PARAM_COUNT,F.keys.size);val s=GeminiProtocol.schema();assertEquals(1,s.getJSONObject("properties").getJSONObject("version").getJSONArray("enum").getInt(0));assertEquals(AstraCommands.allowed.size,s.getJSONObject("properties").getJSONObject("commands").getJSONObject("items").getJSONArray("anyOf").length())}
    @Test fun requestCarriesAudioAndOnlySummaryContext(){val bytes=ByteArray(48){it.toByte()};val text=GeminiProtocol.request("Listen",doc(),0,AudioAttachment("clip.wav","audio/wav",bytes));val root=JSONObject(text);assertFalse(text.contains("api-key"));assertFalse(text.contains("clip.wav"));val parts=root.getJSONArray("contents").getJSONObject(0).getJSONArray("parts");assertArrayEquals(bytes,Base64.getDecoder().decode(parts.getJSONObject(1).getJSONObject("inlineData").getString("data")));assertEquals("application/json",root.getJSONObject("generationConfig").getString("responseMimeType"));assertFalse(root.has("tools"))}
    @Test fun responseRequiresFinishedSingleCandidate(){val json=AstraCommands.envelope("Feedback",emptyList());val response=JSONObject().put("candidates",JSONArray().put(JSONObject().put("finishReason","STOP").put("content",JSONObject().put("parts",JSONArray().put(JSONObject().put("thought",true).put("text","ignore")).put(JSONObject().put("text",json))))));assertEquals(json,GeminiProtocol.response(response.toString()));response.getJSONArray("candidates").getJSONObject(0).put("finishReason","MAX_TOKENS");rejects{GeminiProtocol.response(response.toString())};rejects{GeminiProtocol.response("{\"promptFeedback\":{\"blockReason\":\"SAFETY\"}}")}}
    @Test fun audioAndResponseAreBounded(){rejects{GeminiProtocol.request("x",doc(),0,AudioAttachment("x","audio/wav",ByteArray(GeminiProtocol.MAX_AUDIO_BYTES+1)))};rejects{GeminiProtocol.request("x",doc(),0,AudioAttachment("x","text/plain",byteArrayOf(1)))};assertArrayEquals(byteArrayOf(1,2),GeminiClient.bounded(ByteArrayInputStream(byteArrayOf(1,2)),2));rejects{GeminiClient.bounded(ByteArrayInputStream(byteArrayOf(1,2,3)),2)};rejects{GeminiClient.bounded(ByteArrayInputStream(byteArrayOf(1)),4,AtomicBoolean(true))}}
    @Test fun proposalProjectSurvivesPortableCodec(){val plan=compile(phrase(),cmd("preset","track" to 1,"preset" to "FM Donk"),cmd("sidechain","sourceTrack" to 2,"targetTrack" to 1),cmd("place","track" to 1,"scene" to 1,"beat" to 0));assertEquals(plan.document,ProjectCodec.decode(ProjectCodec.encode(plan.document)))}
}
